import sailpoint.object.ProvisioningPlan;
    import sailpoint.object.ProvisioningPlan.AccountRequest;
    import sailpoint.object.ProvisioningPlan.AttributeRequest;
    import sailpoint.object.ProvisioningResult;
    import java.sql.PreparedStatement;
    import java.util.ArrayList;
    import java.util.List;
    import org.apache.log4j.Logger;

    Logger log = Logger.getLogger("sailpoint.jdbc.JDBCProvisioner");
    ProvisioningResult result = new ProvisioningResult();

    // Helper: pull a single attribute value from an AccountRequest.
    public Object getAttributeRequestValue(AccountRequest acctReq, String attribute) {
      if (acctReq != null) {
        AttributeRequest attrReq = acctReq.getAttributeRequest(attribute);
        if (attrReq != null) {
          return attrReq.getValue();
        }
      }
      return null;
    }

    try {
      List acctReqs = plan.getAccountRequests();
      if (acctReqs != null && acctReqs.size() > 0) {
        for (AccountRequest account : acctReqs) {
          if (AccountRequest.Operation.Modify.equals(account.getOperation())) {
            log.debug("Account Request Operation = Modify");
            String nativeIdentity = (String) account.getNativeIdentity();

            PreparedStatement statement = connection.prepareStatement(
              "update shared_db_table SET email = ?, department = ?, location = ? WHERE username = ?");
            statement.setString(1, (String) getAttributeRequestValue(account, "email"));
            statement.setString(2, (String) getAttributeRequestValue(account, "department"));
            statement.setString(3, (String) getAttributeRequestValue(account, "location"));
            statement.setString(4, (String) nativeIdentity);
            statement.executeUpdate();
            statement.close();

            result.setStatus(ProvisioningResult.STATUS_COMMITTED);
          }
          else if(AccountRequest.Operation.Disable.equals(account.getOperation())) {
            log.debug("Account Request Operation = Disable");
            String nativeIdentity = (String) account.getNativeIdentity();

            PreparedStatement statement = connection.prepareStatement(
              "update shared_db_table SET status = 'Inactive' WHERE username = ?");
            statement.setString(1, (String) nativeIdentity);
            statement.executeUpdate();
            statement.close();

            result.setStatus(ProvisioningResult.STATUS_COMMITTED);
          }
          else if(AccountRequest.Operation.Enable.equals(account.getOperation())) {
            log.debug("Account Request Operation = Enable");
            String nativeIdentity = (String) account.getNativeIdentity();

            PreparedStatement statement = connection.prepareStatement(
              "update shared_db_table SET status = 'Active' WHERE username = ?");
            statement.setString(1, (String) nativeIdentity);
            statement.executeUpdate();
            statement.close();

            result.setStatus(ProvisioningResult.STATUS_COMMITTED);
          }
          else {
            log.debug("Unsupported operation: " + account.getOperation());
          }
        }
      }
    }
    catch (Exception e) {
      log.debug("JDBC provisioning failed: " + e);
      result.setStatus(ProvisioningResult.STATUS_FAILED);
      result.addError(e.toString());
    }

    return result;
